('bmlt-malaria-blood-parasites-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',4600,$json${"question":"Which stain is routinely used for malaria parasite examination in thick and thin blood films?","translation":"","options":["Giemsa stain","Gram stain","India ink","Albert stain"],"correctIndex":0,"explanation":"Giemsa stain provides useful contrast for malaria parasite morphology in blood films.","explanationNe":"Giemsa stain ले blood film मा malaria parasite को morphology स्पष्ट देखाउँछ।","topic":"Malaria microscopy"}$json$::jsonb,true),
('bmlt-malaria-blood-parasites-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',4601,$json${"question":"What is the main advantage of a thick blood film for malaria diagnosis?","translation":"","options":["Greater sensitivity due to concentration of blood elements","Better preservation of red cell morphology","Species identification is always easier","It requires no staining"],"correctIndex":0,"explanation":"Thick films concentrate a larger blood volume and improve parasite detection, though red cells are lysed.","explanationNe":"Thick film मा बढी रगत जाँचिने भएकाले parasite पत्ता लगाउने sensitivity बढ्छ।","topic":"Thick film"}$json$::jsonb,true),
('bmlt-malaria-blood-parasites-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',4602,$json${"question":"What is the main advantage of a thin blood film in malaria microscopy?","translation":"","options":["Better assessment of parasite morphology and species identification","Concentration of all parasites into one field","Detection of bacterial spores","Quantification of urine casts"],"correctIndex":0,"explanation":"Thin films preserve red cell morphology and help identify Plasmodium species and parasitaemia.","explanationNe":"Thin film ले RBC morphology जोगाउँछ र Plasmodium species पहिचानमा मद्दत गर्छ।","topic":"Thin film"}$json$::jsonb,true),
('bmlt-malaria-blood-parasites-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4603,$json${"question":"Which Plasmodium species commonly enlarges infected red blood cells and may show Schüffner's dots?","translation":"","options":["Plasmodium vivax","Plasmodium falciparum","Plasmodium malariae","Plasmodium knowlesi"],"correctIndex":0,"explanation":"P. vivax typically enlarges infected erythrocytes and may show Schüffner's stippling.","explanationNe":"P. vivax ले संक्रमित RBC ठूलो बनाउन सक्छ र Schüffner's dots देखिन सक्छ।","topic":"Plasmodium morphology"}$json$::jsonb,true),
('bmlt-malaria-blood-parasites-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',4604,$json${"question":"Multiple delicate ring forms in a single red blood cell are particularly suggestive of:","translation":"","options":["Plasmodium falciparum","Plasmodium vivax","Plasmodium malariae","Babesia microti"],"correctIndex":0,"explanation":"Multiple delicate rings and appliqué forms are characteristic clues for P. falciparum.","explanationNe":"एउटै RBC मा धेरै delicate ring र appliqué form देखिनु P. falciparum को संकेत हो।","topic":"Plasmodium morphology"}$json$::jsonb,true),
